INSERT INTO reviews (id,product_id,user_id,rating,title,body,is_verified_purchase) VALUES
(1,1,1,5,'Tastes like Mangalore','I have bought four sukka masalas online and returned three. This one actually has roasted coconut in it — you can see it in the grind. Made kori sukka on Sunday and my mother asked which shop I got it from, which is the highest praise available in my family.',TRUE),
(2,1,2,5,'Three spoons is enough','Went in with my usual heavy hand and it was too much. Follow the instruction on the label. Genuinely strong stuff.',TRUE),
(3,1,4,4,NULL,'Excellent flavour. Clumped a bit in Bombay humidity but that is on the weather, not them. Broke it up with a fork and it was fine.',TRUE),
(4,5,3,5,'The stone is attached','Whoever cut these knew what they were doing — every piece has the stone still on it. Sharp and salty right now, and I am told it settles by month three. Already ordered a second jar to keep unopened.',TRUE),
(5,5,5,5,NULL,'Oil sits properly above the pieces, no shortcuts. Curd rice has been upgraded permanently.',TRUE),
(6,8,6,5,'Arrived cold and alive','Delivered chilled, still risen, smelled exactly right. First dosa was rubbish because my tawa was not hot enough; the next eleven were perfect. That one is my fault.',TRUE),
(7,8,1,4,'Order the day before','Great batter, just plan for it — four days is a real limit, not a suggestion. I now order it on Thursday for the weekend.',TRUE),
(8,4,3,5,'You need less than you think','Went in with two spoons out of habit and the sambar nearly walked out of the pot. One is plenty. The roasted dal makes it thick without any other help.',TRUE),
(9,10,2,5,'Pale gold, not brown','Fried in actual coconut oil, and you can tell from the smell when the bag opens. The 250 g lasted an evening, which is a complaint about me.',TRUE),
(10,13,5,5,'The soft kind','This is the porous ghee one, not the hard fudge everyone else ships. It took an extra day to arrive because they make it after you order and that is exactly the right trade.',TRUE),
(11,2,6,4,NULL,'Crust is legitimately good — the besan trick works. Marinate the full hour, do not rush it like I did the first time.',TRUE),
(12,11,4,5,'Snaps properly','Every one of them broke clean instead of bending. Sizes are all slightly different, which is how you know a machine did not make them.',TRUE),
(13,12,1,4,NULL,'Twenty in a pack, roasts on the flame in about fifteen seconds. Nothing surprising here, which is the point of a papad.',TRUE),
(14,6,3,5,'No oil at all','Exactly the type my grandmother made. Skins have gone soft and translucent, which only happens with real time in salt.',TRUE),
(15,14,2,5,'Rolled thin','You can see the puran through the dough. Reheated with ghee on a tawa as instructed. Four disappeared between two people.',TRUE),
(16,3,5,4,'Works on prawns too','Used it on bangda first, then prawns. The tamarind is what makes it — most fish masalas just add more chilli and hope.',TRUE);
